import fs, { type FileRef } from "@rcompat/fs";
import is from "@rcompat/is";
import { readConfig, normalizePackageEntry, type PackageEntry } from "#utils/config";
import { parseSpecifier } from "#utils/parse-specifier";
import { packageJsonSchema, type PowerUpProperty } from "#schemas/package";
import power_errors from "#errors/powerErrors";
import {
  MAIN_FOLDER,
  GLOBAL_ROOT,
  MULTI_USE_FOLDER,
  SINGLE_USE_FOLDER,
  PACKAGE_FILE,
  type PowerUpType,
  CLI_NAME,
} from "#constants";

export interface ResolvedPowerUp {
  type: PowerUpType;
  folder: FileRef;
  packageName: string;
  location: "local" | "global";
}

interface PackageLocation {
  packageName: string;
  packageDir: FileRef;
  powerups: PowerUpProperty;
  location: "local" | "global";
}

